class Component extends DCLogic {
  rootRef = MrbRef();

  state = {
    w: 1200, idx: 0, answers: {}, sels: {}, held: {}, elapsed: 0, paused: false,
    sheet: false, zoom: false, view: 'q', handedAt: null, handing: false,
    resumed: false, net: null, scn: null, live: false, late: false, realOff: false
  };

  KEY = 'mrbadmusai.assignment.8rSc1.a5.v1';
  DUE = 'DUE THU 18 SEP, 18:00';

  /* Rungs 1-2 of the four authored KS3 lessons in this topic. Every option
     carries the feedback written against it in the lesson. a = answer index. */
  questions = [
    { t: 'USING A MICROSCOPE', g: 'micro',
      q: 'Which label points to the objective lens?',
      o: ['A', 'B', 'C', 'D'],
      f: ['A is the eyepiece \u2014 the lens you look down.',
          'B is the focus wheel. It moves the tube up and down and magnifies nothing.',
          'Right. The objective sits closest to the slide, so it magnifies first.',
          'D is the stage, the platform the slide rests on.'], a: 2 },
    { t: 'USING A MICROSCOPE', g: null,
      q: 'An eyepiece lens of 10 and an objective lens of 40 are used together. What is the total magnification?',
      o: ['50, the two numbers added together',
          '400, the two numbers multiplied together',
          '40, because the objective does all of the magnifying',
          '4, the objective divided by the eyepiece'],
      f: ['Magnification multiplies at each lens. It is never added.',
          'Right. Each lens magnifies the image the next one receives, so the powers multiply.',
          'The objective magnifies first, then the eyepiece magnifies that image again.',
          'Nothing is divided here. Both lenses enlarge the image.'], a: 1 },
    { t: 'USING A MICROSCOPE', g: null,
      q: 'You have just put a new slide on the stage. Which objective lens do you start with?',
      o: ['The lowest power, so more of the slide is in view',
          'The highest power, so you see the detail straight away',
          'Any of them \u2014 the order makes no difference',
          'The highest power, then focus using the stage clips'],
      f: ['Right. A wide field of view is how you find the specimen before you magnify it.',
          'At high power the field of view is tiny, and you will not find the specimen at all.',
          'It does matter. Starting high leaves you hunting across a very small field.',
          'The clips only hold the slide down. They focus nothing.'], a: 0 },
    { t: 'USING A MICROSCOPE', g: null,
      q: 'Why must the specimen on a slide be cut as a very thin section?',
      o: ['So light can pass through it',
          'So it fits under the coverslip',
          'So it does not dry out',
          'So the stain does not run'],
      f: ['Right. A light microscope shines light through the specimen, and thick tissue blocks it.',
          'A thicker specimen would still fit. The problem is what happens to the light.',
          'Thin sections dry out faster, which is why they are mounted in a drop of water.',
          'Stain is there to add contrast. It has nothing to do with thickness.'], a: 0 },
    { t: 'USING A MICROSCOPE', g: 'bubbles',
      q: 'Slide 1 was mounted badly. What went wrong when the coverslip was put on?',
      o: ['It was dropped flat, trapping air underneath',
          'Too much stain was used',
          'The section was cut too thin',
          'It was pressed down too hard'],
      f: ['Right. Lower it at an angle from one edge and the air is pushed out ahead of it.',
          'Stain colours the specimen. It does not leave round, dark-edged circles.',
          'A thin section is what you want \u2014 it lets the light through.',
          'Pressing hard cracks the coverslip. It does not make bubbles.'], a: 0 },
    { t: 'USING A MICROSCOPE', g: 'fov',
      q: 'At a total magnification of 100 you can see eight cells across the field of view. You switch to 400. About how many will you see across it?',
      o: ['Thirty-two', 'Two', 'Eight, the same', 'Four'],
      f: ['The image gets bigger, so less of the slide fits in view, not more.',
          'Right. Four times the magnification shows about a quarter of the width, so two cells.',
          'Each cell now looks four times wider, so fewer of them fit across.',
          'That would be right for doubling the magnification. This is four times.'], a: 1 },
    { t: 'ANIMAL AND PLANT CELLS', g: 'plant',
      q: 'The diagram shows a plant cell. Which label points to the part where photosynthesis happens?',
      o: ['A', 'B', 'C', 'D'],
      f: ['A is the cell wall. It supports the cell and lets water through.',
          'B is the nucleus. It holds the genetic material.',
          'Right. Chloroplasts absorb the light, which is why animal cells have none.',
          'D is the vacuole. It stores sap and keeps the cell firm.'], a: 2 },
    { t: 'ANIMAL AND PLANT CELLS', g: null,
      q: 'A plant cell holds its shape even when it is full of water. Which part is responsible?',
      o: ['The cell membrane', 'The cell wall', 'The vacuole', 'The cytoplasm'],
      f: ['Every cell has a membrane, and it is far too thin to hold a shape.',
          'Right. The wall is made of cellulose, rigid enough to resist the pressure inside.',
          'The vacuole pushes outwards \u2014 but something has to resist that push.',
          'Cytoplasm is where the reactions happen. It is a jelly, not a support.'], a: 1 },
    { t: 'LIFE PROCESSES AND CELLS', g: null,
      q: 'Which part of a cell controls what passes in and out of it?',
      o: ['The cell wall', 'The cell membrane', 'The vacuole', 'The nucleus'],
      f: ['Only plant cells have a wall, and its job is support.',
          'Right. The membrane is partially permeable: some substances pass through, others do not.',
          'The vacuole stores sap, and it sits inside the cell.',
          'The nucleus holds the instructions. It controls the cell, not the traffic.'], a: 1 },
    { t: 'LIFE PROCESSES AND CELLS', g: null,
      q: 'Why does a cell need a nucleus?',
      o: ['It holds the instructions for making proteins',
          'It releases energy from glucose',
          'It controls what enters the cell',
          'It keeps the cell rigid'],
      f: ['Right. The genetic material in the nucleus is the instruction set the cell works from.',
          'That is the mitochondria.',
          'That is the membrane.',
          'That is the cell wall, and only in plants.'], a: 0 },
    { t: 'LIFE PROCESSES AND CELLS', g: null,
      q: 'Muscle cells contain far more mitochondria than skin cells. Why?',
      o: ['They need more energy released from glucose',
          'They need to store more water',
          'They divide far more often',
          'They have no nucleus, so there is room'],
      f: ['Right. Mitochondria release energy in respiration, and contracting muscle needs a lot of it.',
          'Mitochondria store nothing. In plant cells the vacuole holds water.',
          'Cell division is run from the nucleus, not the mitochondria.',
          'Muscle cells do have nuclei \u2014 several of them, in fact.'], a: 0 },
    { t: 'SPECIALISED CELLS', g: 'cells',
      q: 'Which of these cells is adapted to absorb water from the soil?',
      o: ['A', 'B', 'C', 'D'],
      f: ['A is shaped to carry oxygen \u2014 the dip gives it more surface for the same volume.',
          'B has a tail for swimming towards an egg cell.',
          'Right. The long projection gives a huge surface area in contact with the soil.',
          'D has hairs that sweep mucus along an airway.'], a: 2 },
    { t: 'SPECIALISED CELLS', g: null,
      q: 'A red blood cell has no nucleus. What does that make room for?',
      o: ['More haemoglobin, so it carries more oxygen',
          'More mitochondria, so it releases more energy',
          'More water, so it can change shape',
          'A larger vacuole'],
      f: ['Right. Losing the nucleus frees space, and that space is filled with haemoglobin.',
          'Red blood cells have almost no mitochondria \u2014 they do not use the oxygen they carry.',
          'They do bend to squeeze through capillaries, but that is the membrane, not stored water.',
          'Vacuoles are a plant cell structure.'], a: 0 },
    { t: 'SPECIALISED CELLS', g: null,
      q: 'Why does a sperm cell have a tail?',
      o: ['To swim towards the egg cell',
          'To hold on to the egg cell',
          'To carry extra genetic material',
          'To absorb food from around it'],
      f: ['Right. The tail is the only way it moves, with mitochondria packed behind it for energy.',
          'The head does the joining, not the tail.',
          'All of the genetic material is in the head.',
          'The tail is for movement. Nothing is absorbed through it.'], a: 0 },
    { t: 'USING A MICROSCOPE', g: 'scale',
      q: 'The cell in the figure measures 0.06 mm across. What is that in micrometres?',
      o: ['6', '60', '600', '0.06'],
      f: ['You have divided by ten. One millimetre is a thousand micrometres.',
          'Right. One millimetre is 1000 micrometres, so 0.06 mm is 60 of them.',
          'That would be 0.6 mm \u2014 ten times too big.',
          'The number cannot stay the same when the unit changes.'], a: 1 },
    { t: 'LIFE PROCESSES AND CELLS', g: null,
      q: 'Which list goes from the smallest to the largest?',
      o: ['Cell, tissue, organ, organ system',
          'Tissue, cell, organ, organ system',
          'Cell, organ, tissue, organ system',
          'Organ, cell, tissue, organ system'],
      f: ['Right. Cells of one kind make a tissue, tissues make an organ, organs make a system.',
          'A tissue is built out of cells, so the cell comes first.',
          'An organ is built out of several tissues, so the tissue comes before it.',
          'The cell is the smallest unit of all, so nothing comes before it.'], a: 0 }
  ];

  /* the questions this student got wrong, and which distractor they picked */
  wrongPlan = { 2: 1, 4: 3, 10: 3 };

  figCaptions = {
    micro: 'FIGURE \u00B7 LIGHT MICROSCOPE',
    bubbles: 'FIGURE \u00B7 TWO MOUNTED SLIDES, SEEN DOWN THE MICROSCOPE',
    fov: 'FIGURE \u00B7 THE SAME SLIDE AT TWO MAGNIFICATIONS',
    plant: 'FIGURE \u00B7 PLANT CELL',
    cells: 'FIGURE \u00B7 FOUR SPECIALISED CELLS',
    scale: 'FIGURE \u00B7 ONE CELL WITH A SCALE BAR',
    slot: 'FIGURE \u00B7 LESSON 02'
  };

  count() {
    const n = Math.round(this.props.questionCount ?? 15);
    return Math.max(6, Math.min(this.questions.length, n));
  }

  seedAnswers(n) {
    const a = {};
    for (let i = 0; i < n; i++) a[i] = this.wrongPlan[i] != null ? this.wrongPlan[i] : this.questions[i].a;
    return a;
  }

  seedFor(scn) {
    const total = this.count();
    const base = { held: {}, sels: {}, resumed: false, late: false, view: 'q', handedAt: null, sheet: false, zoom: false, handing: false, net: null };
    if (scn === 'First open') return Object.assign(base, { answers: {}, idx: 0, elapsed: 0 });
    if (scn === 'Mid-way') return Object.assign(base, { answers: this.seedAnswers(6), idx: 6, elapsed: 372 });
    if (scn === 'Returning') return Object.assign(base, { answers: this.seedAnswers(6), idx: 6, elapsed: 372, resumed: true });
    if (scn === 'All answered') return Object.assign(base, { answers: this.seedAnswers(total), idx: total - 1, elapsed: 1122 });
    if (scn === 'Handed in') return Object.assign(base, { answers: this.seedAnswers(total), idx: 0, elapsed: 1122, view: 'done', handedAt: '17 SEP, 20:41' });
    if (scn === 'Late, not handed in') return Object.assign(base, { answers: this.seedAnswers(9), idx: 9, elapsed: 641, resumed: true, late: true });
    if (scn === 'Handed in late') return Object.assign(base, { answers: this.seedAnswers(total), idx: 0, elapsed: 1268, view: 'done', handedAt: '20 SEP, 19:07', late: true });
    return null;
  }

  loadLive() {
    const empty = { answers: {}, sels: {}, held: {}, idx: 0, elapsed: 0, view: 'q', handedAt: null, resumed: false, late: false, sheet: false, zoom: false, handing: false, net: null };
    try {
      const raw = window.localStorage.getItem(this.KEY);
      if (!raw) return empty;
      const d = JSON.parse(raw) || {};
      const answers = d.answers || {};
      return Object.assign(empty, {
        answers: answers, sels: d.sels || {}, held: d.held || {}, idx: d.idx || 0, elapsed: d.elapsed || 0,
        view: d.view || 'q', handedAt: d.handedAt || null, late: !!d.late,
        resumed: Object.keys(answers).length > 0
      });
    } catch (e) { return empty; }
  }

  saveLive() {
    if (!this.state.live) return;
    const s = this.state;
    try {
      window.localStorage.setItem(this.KEY, JSON.stringify({
        answers: s.answers, sels: s.sels, held: s.held, idx: s.idx, elapsed: s.elapsed,
        view: s.view, handedAt: s.handedAt, late: s.late
      }));
    } catch (e) { /* private mode: the page still works, it just forgets */ }
  }

  applyScenario(scn) {
    const live = scn === 'Live, saved';
    const seed = live ? this.loadLive() : this.seedFor(scn);
    this.setState(Object.assign({ scn: scn, live: live }, seed));
  }

  componentDidMount() {
    const el = this.rootRef.current;
    this.measure = () => {
      if (!this.rootRef.current) return;
      const w = this.rootRef.current.getBoundingClientRect().width;
      if (w && Math.abs(w - this.state.w) > 1) this.setState({ w: w });
    };
    window.addEventListener('resize', this.measure);
    window.addEventListener('orientationchange', this.measure);
    if (window.visualViewport) window.visualViewport.addEventListener('resize', this.measure);
    let ticks = 0;
    this.poll = setInterval(() => { this.measure(); if (++ticks > 24) clearInterval(this.poll); }, 250);
    this.measure();
    requestAnimationFrame(this.measure);

    /* offline-file routing: #first #midway #returning #all #done #late #donelate */
    const map = {
      first: 'First open', midway: 'Mid-way', returning: 'Returning', all: 'All answered',
      done: 'Handed in', late: 'Late, not handed in', donelate: 'Handed in late', live: 'Live, saved'
    };
    const h = (window.location.hash || '').replace('#', '').toLowerCase();
    this.applyScenario(map[h] || this.props.scenario || 'Mid-way');

    this.lastAct = Date.now();
    this.bump = () => {
      this.lastAct = Date.now();
      if (this.state.paused) this.setState({ paused: false });
    };
    ['pointerdown', 'keydown', 'wheel', 'touchstart'].forEach((n) => window.addEventListener(n, this.bump, { passive: true }));
    window.addEventListener('scroll', this.bump, { passive: true });

    /* counts up, pauses after 60s of no touch, keypress or scroll */
    this.clock = setInterval(() => {
      const s = this.state;
      if (s.view !== 'q' || s.handedAt || s.handing) return;
      if (Date.now() - this.lastAct > 60000) { if (!s.paused) this.setState({ paused: true }); return; }
      this.setState((p) => ({ elapsed: p.elapsed + 1 }), () => { if (this.state.elapsed % 10 === 0) this.saveLive(); });
    }, 1000);

    this.netOn = () => this.setState({ realOff: false });
    this.netOff = () => this.setState({ realOff: true });
    window.addEventListener('online', this.netOn);
    window.addEventListener('offline', this.netOff);
    if (window.navigator && window.navigator.onLine === false) this.setState({ realOff: true });
    this.prevOff = this.isOffline();
  }

  componentWillUnmount() {
    window.removeEventListener('resize', this.measure);
    window.removeEventListener('orientationchange', this.measure);
    if (window.visualViewport) window.visualViewport.removeEventListener('resize', this.measure);
    ['pointerdown', 'keydown', 'wheel', 'touchstart'].forEach((n) => window.removeEventListener(n, this.bump));
    window.removeEventListener('scroll', this.bump);
    window.removeEventListener('online', this.netOn);
    window.removeEventListener('offline', this.netOff);
    clearInterval(this.poll); clearInterval(this.clock); clearInterval(this.drainT); clearTimeout(this.handT);
  }

  componentDidUpdate(prev) {
    if (prev.scenario !== this.props.scenario && this.props.scenario) this.applyScenario(this.props.scenario);
    if (prev.questionCount !== this.props.questionCount) {
      const total = this.count();
      if (this.state.idx > total - 1) this.setState({ idx: total - 1 });
      if (this.state.scn && this.state.scn !== 'Live, saved') this.applyScenario(this.state.scn);
    }
    const off = this.isOffline();
    if (this.prevOff !== off) {
      this.prevOff = off;
      if (!off && Object.keys(this.state.held).length) this.drain();
      else if (off) this.setState({ net: null });
    }
  }

  isOffline() { return !!(this.props.offline ?? false) || this.state.realOff; }

  /* answers made offline are held on the device, then sent one at a time */
  drain() {
    const ids = Object.keys(this.state.held);
    this.setState({ net: 'sent', sentN: ids.length });
    let i = 0;
    clearInterval(this.drainT);
    this.drainT = setInterval(() => {
      if (i >= ids.length) {
        clearInterval(this.drainT);
        setTimeout(() => this.setState({ net: null }), 1100);
        return;
      }
      const k = ids[i++];
      this.setState((s) => { const h = Object.assign({}, s.held); delete h[k]; return { held: h }; }, () => this.saveLive());
    }, 130);
  }

  /* a tap selects; nothing is marked until Confirm answer */
  select = (oi) => {
    const s = this.state;
    if (s.answers[s.idx] != null || s.handedAt) return;
    this.lastAct = Date.now();
    this.setState((p) => {
      const sl = Object.assign({}, p.sels); sl[p.idx] = oi;
      return { sels: sl, resumed: false, paused: false };
    }, () => this.saveLive());
  };

  confirm = () => {
    const s = this.state;
    const oi = s.sels[s.idx];
    if (oi == null || s.answers[s.idx] != null || s.handedAt) return;
    const off = this.isOffline();
    this.lastAct = Date.now();
    this.setState((p) => {
      const a = Object.assign({}, p.answers); a[p.idx] = oi;
      const h = Object.assign({}, p.held); if (off) h[p.idx] = 1;
      return { answers: a, held: h, resumed: false, paused: false };
    }, () => this.saveLive());
  };

  go = (i) => {
    const total = this.count();
    const n = Math.max(0, Math.min(total - 1, i));
    this.setState({ idx: n, view: 'q', sheet: false, zoom: false, resumed: false }, () => this.saveLive());
  };
  next = () => this.go(this.state.idx + 1);
  back = () => this.go(this.state.idx - 1);
  jumpNext = () => {
    const total = this.count();
    for (let i = 0; i < total; i++) if (this.state.answers[i] == null) return this.go(i);
  };
  toggleSheet = () => this.setState((s) => ({ sheet: !s.sheet }));
  toggleZoom = () => this.setState((s) => ({ zoom: !s.zoom }));
  goSummary = () => this.setState({ view: 'done', sheet: false, zoom: false }, () => this.saveLive());
  reviewAll = () => this.go(0);
  goClass = () => {
    if (window.history.length > 1) window.history.back();
    else window.location.href = 'Class View.dc.html';
  };

  handIn = () => {
    const stamp = this.state.late ? '20 SEP, 19:07' : '17 SEP, 20:41';
    this.setState({ handing: true, handedAt: stamp, sheet: false, zoom: false }, () => this.saveLive());
    clearTimeout(this.handT);
    this.handT = setTimeout(() => this.setState({ handing: false, view: 'done' }, () => this.saveLive()), 1350);
  };

  pad(n) { return n < 10 ? '0' + n : String(n); }
  mmss(s) { return this.pad(Math.floor(s / 60)) + ':' + this.pad(s % 60); }

  renderVals() {
    const st = this.state;
    const forced = { 'Phone 360': 360, 'Phone 390': 390, 'Tablet 820': 820, 'Desktop 1460': 1460 }[this.props.layout ?? 'Auto'];
    const W = forced || st.w;
    const desk = W >= 1024;
    const wide = W >= 720;
    const pad = (n) => this.pad(n);

    const total = this.count();
    const idx = Math.min(st.idx, total - 1);
    const q = this.questions[idx];
    const answers = st.answers;
    const handed = !!st.handedAt;

    let nDone = 0, nRight = 0;
    for (let i = 0; i < total; i++) {
      if (answers[i] != null) { nDone++; if (answers[i] === this.questions[i].a) nRight++; }
    }
    const nLeft = total - nDone;
    const allDone = nLeft === 0;
    const pick = answers[idx];
    const locked = pick != null || handed;
    const offline = this.isOffline();
    const heldKeys = Object.keys(st.held);

    /* figures: q.g when the lesson ships one; the slot shows what a set figure occupies */
    const figMode = this.props.figures ?? 'Six of them';
    const figKey = figMode === 'None' ? null : (q.g || (figMode === 'Every question' ? 'slot' : null));
    const zoom = st.zoom;

    const keys = ['A', 'B', 'C', 'D'];
    const cream = '#FFFDF8';
    const sel = st.sels[idx];
    const options = q.o.map((t, i) => {
      const isPick = pick === i, isAns = q.a === i;
      const s = !locked ? (sel === i ? 'sel' : 'idle') : isPick && isAns ? 'right' : isPick ? 'wrong' : isAns ? 'answer' : 'off';
      const o = { key: keys[i], text: t, onClick: () => this.select(i), cursor: locked ? 'default' : 'pointer' };
      if (s === 'sel') return Object.assign(o, {
        bg: 'var(--st-paper)', border: '2px solid var(--st-ink)', color: 'var(--st-ink)',
        keyBg: 'var(--st-ink)', keyBorder: '2px solid var(--st-ink)', keyColor: cream,
        keyAnim: 'none', tick: false, cross: false, status: '', note: ''
      });
      if (s === 'idle') return Object.assign(o, {
        bg: 'var(--st-paper)', border: '1.5px solid var(--st-rule)', color: 'var(--st-ink)',
        keyBg: 'transparent', keyBorder: '1.5px solid var(--st-rule-strong)', keyColor: 'var(--st-caption)',
        keyAnim: 'none', tick: false, cross: false, status: '', note: ''
      });
      if (s === 'right') return Object.assign(o, {
        bg: 'var(--ks3-ok-tint)', border: '2px solid var(--ks3-ok)', color: 'var(--st-ink)',
        keyBg: 'var(--ks3-ok-text)', keyBorder: '2px solid var(--ks3-ok-text)', keyColor: cream,
        keyAnim: 'mrbMark .3s ease-out both', tick: true, cross: false,
        markColor: 'var(--ks3-ok-text)', status: 'RIGHT', statusColor: 'var(--ks3-ok-text)',
        note: q.f[i], noteRule: 'var(--ok-border)', noteColor: 'var(--st-body)'
      });
      if (s === 'wrong') return Object.assign(o, {
        bg: 'var(--err-bg)', border: '2px solid var(--err)', color: 'var(--st-ink)',
        keyBg: 'var(--err)', keyBorder: '2px solid var(--err)', keyColor: cream,
        keyAnim: 'mrbMark .3s ease-out both', tick: false, cross: true,
        markColor: 'var(--err)', status: 'NOT THIS ONE', statusColor: 'var(--err)',
        note: q.f[i], noteRule: 'var(--err-border)', noteColor: 'var(--st-body)'
      });
      if (s === 'answer') return Object.assign(o, {
        bg: 'var(--st-paper)', border: '2px solid var(--ks3-ok)', color: 'var(--st-ink)',
        keyBg: 'transparent', keyBorder: '2px solid var(--ks3-ok)', keyColor: 'var(--ks3-ok-text)',
        keyAnim: 'none', tick: true, cross: false,
        markColor: 'var(--ks3-ok)', status: 'THE ANSWER', statusColor: 'var(--ks3-ok-text)',
        note: q.f[i], noteRule: 'var(--st-rule-soft)', noteColor: 'var(--st-muted)'
      });
      return Object.assign(o, {
        bg: 'transparent', border: '1px solid var(--st-rule-fact)', color: 'var(--st-faint)',
        keyBg: 'transparent', keyBorder: '1px solid var(--st-rule-fact)', keyColor: 'var(--st-faint)',
        keyAnim: 'none', tick: false, cross: false, status: '', note: ''
      });
    });

    const markFor = (i) => {
      const a = answers[i];
      const done = a != null;
      const ok = done && a === this.questions[i].a;
      const isHeld = !!st.held[i];
      return {
        num: pad(i + 1), ok: ok, bad: done && !ok, left: !done,
        held: isHeld, current: i === idx,
        onClick: () => (wide || st.view === 'done' ? this.go(i) : this.toggleSheet())
      };
    };

    const markers = [];
    for (let i = 0; i < total; i++) {
      const m = markFor(i);
      const hatch = ',repeating-linear-gradient(45deg,rgba(251,243,230,0.62) 0 3px,rgba(251,243,230,0) 3px 6px)';
      let bg = 'var(--st-rule-soft)', bd = '1px solid var(--st-rule)', mark = 'transparent';
      if (m.ok) { bg = m.held ? 'linear-gradient(var(--st-ink),var(--st-ink))' + hatch : 'var(--st-ink)'; bd = 'none'; mark = 'var(--st-ground)'; }
      else if (m.bad) { bg = 'var(--err-bg)'; bd = '1.5px solid var(--err)'; mark = 'var(--err)'; }
      markers.push(Object.assign(m, {
        h: m.current ? '26px' : m.left ? '10px' : '22px',
        bg: bg, bd: bd, mark: mark,
        ring: m.current ? '0 0 0 2px var(--st-accent)' : 'none',
        anim: st.resumed && !m.left ? 'mrbMark .34s ' + (0.04 * i).toFixed(2) + 's ease-out both' : 'none'
      }));
    }

    const grid = [];
    for (let i = 0; i < total; i++) {
      const m = markFor(i);
      grid.push(Object.assign(m, {
        bg: m.ok ? 'var(--st-ink)' : m.bad ? 'var(--err-bg)' : 'transparent',
        bd: m.ok ? 'none' : m.bad ? '1.5px solid var(--err)' : '1.2px dashed var(--st-rule-strong)',
        numColor: m.ok ? 'var(--st-ground)' : m.bad ? 'var(--err)' : 'var(--st-ghost)',
        mark: m.ok ? 'var(--st-ground)' : 'var(--err)',
        ring: m.current ? '0 0 0 2px var(--st-accent)' : 'none',
        onClick: () => this.go(i)
      }));
    }

    const endMarks = [];
    for (let i = 0; i < total; i++) {
      const m = markFor(i);
      endMarks.push(Object.assign(m, {
        bg: m.ok ? 'var(--st-cream)' : 'transparent',
        bd: m.ok ? 'none' : m.bad ? '1.5px solid var(--st-ember)' : '1px solid var(--st-room-line-strong)',
        mark: m.ok ? 'var(--st-ink)' : 'var(--st-ember)',
        onClick: () => this.go(i)
      }));
    }

    const wrongList = [];
    for (let i = 0; i < total; i++) {
      const a = answers[i];
      if (a == null || a === this.questions[i].a) continue;
      const qq = this.questions[i];
      wrongList.push({
        num: pad(i + 1), q: qq.q,
        yourKey: keys[a], yourText: qq.o[a], yourNote: qq.f[a],
        ansKey: keys[qq.a], ansText: qq.o[qq.a], ansNote: qq.f[qq.a],
        jumpLabel: 'LOOK AT QUESTION ' + pad(i + 1),
        onClick: () => this.go(i)
      });
    }

    const pctVal = nDone ? Math.round((nRight / total) * 100) : 0;
    const netNote = st.net === 'sent'
      ? 'BACK ONLINE \u00B7 ' + pad(st.sentN || 0) + ' SENT'
      : offline ? 'OFFLINE \u00B7 ' + pad(heldKeys.length) + ' HELD ON THIS DEVICE' : '';

    const onQ = st.view === 'q' && !st.handing;
    const onDone = st.view === 'done' && !st.handing;

    return {
      rootRef: this.rootRef,
      frameW: forced ? forced + 'px' : '100%',
      frameEdge: forced ? '1px solid var(--st-rule)' : 'none',
      wide: wide,

      /* the seven discrete switches. everything else is clamp() on cqw */
      shellDisplay: desk ? 'grid' : 'block',
      shellCols: desk ? 'minmax(0,1fr) 320px' : 'none',
      optCols: desk ? '1fr 1fr' : 'minmax(0,1fr)',
      showStrip: !desk && onQ,
      showReadout: !desk && onQ,
      rail: desk && onQ,
      markerHit: wide ? '40px' : '44px',
      wrongCols: desk ? 'repeat(2,minmax(0,1fr))' : 'minmax(0,1fr)',

      onQ: onQ, onDone: onDone, handing: st.handing,
      screenLabel: onDone ? (st.late ? 'Handed in late' : 'Handed in') : handed ? 'Review' : 'Question ' + pad(idx + 1),

      clock: this.mmss(st.elapsed),
      clockColor: st.paused || handed ? 'var(--st-muted)' : 'var(--st-ink)',
      dotBg: st.paused || handed ? 'transparent' : 'var(--st-accent)',
      dotBorder: st.paused || handed ? '1.5px solid var(--st-rule-strong)' : 'none',
      timerLabel: handed ? 'TOTAL' : st.paused ? 'PAUSED' : '',
      chipLate: st.late, chipHanded: handed,
      offline: offline, netNote: netNote,
      netSwatch: st.net === 'sent' ? 'var(--st-ink)' : 'repeating-linear-gradient(45deg,var(--st-ink) 0 3px,var(--st-chip-tint) 3px 6px)',
      heldCount: heldKeys.length,

      markers: markers, grid: grid, endMarks: endMarks,
      sheet: st.sheet && !desk, toggleSheet: this.toggleSheet,
      sheetTitle: 'All ' + total + ' questions',
      answeredText: 'ANSWERED ' + pad(nDone) + ' / ' + pad(total),
      hasRight: nDone > 0, rightText: pad(nRight) + ' RIGHT',
      leftText: nLeft ? pad(nLeft) + ' LEFT' : 'NONE LEFT',
      leftColor: nLeft ? 'var(--st-caption)' : 'var(--ks3-accent-text)',
      railStats: [
        { label: 'ANSWERED', value: pad(nDone) + '/' + pad(total), color: 'var(--st-ink)' },
        { label: 'RIGHT', value: pad(nRight), color: 'var(--st-ink)' },
        { label: 'TIME', value: this.mmss(st.elapsed), color: st.paused ? 'var(--st-muted)' : 'var(--st-ink)' }
      ].map((s, i) => Object.assign(s, { edge: i < 2 ? '1px solid var(--st-rule-fact)' : 'none', pl: i ? '13px' : '0' })),

      headMeta: 'WEEK 04 \u00B7 ' + total + ' QUESTIONS',
      dueLead: 'CELLS & MICROSCOPY \u00B7 ' + this.DUE,
      dueFlag: st.late ? '\u00B7 2 DAYS LATE' : '',
      qEyebrow: 'Question ' + pad(idx + 1) + ' of ' + pad(total) + ' \u00B7 ' + q.t,
      qText: q.q,
      options: options,

      hasFig: !!figKey,
      figMicro: figKey === 'micro', figBubbles: figKey === 'bubbles', figFov: figKey === 'fov',
      figPlant: figKey === 'plant', figCells: figKey === 'cells', figScale: figKey === 'scale',
      figSlot: figKey === 'slot',
      figCaption: figKey ? this.figCaptions[figKey] : '',
      figHint: figKey === 'slot' ? '' : zoom ? 'TAP TO SHRINK' : 'TAP TO ENLARGE',
      figCap: zoom ? 'min(72vh,620px)' : 'clamp(132px,34cqw,232px)',
      toggleZoom: this.toggleZoom,

      showAction: onQ,
      back: st.idx > 0 ? this.back : () => {},
      backCursor: idx > 0 ? 'pointer' : 'default',
      backColor: idx > 0 ? 'var(--st-body)' : 'var(--st-faint)',
      backBorder: idx > 0 ? 'var(--st-btn-border)' : 'var(--st-rule-fact)',
      next: this.next, jumpNext: this.jumpNext, handIn: this.handIn, goSummary: this.goSummary,
      confirm: this.confirm, showConfirm: !locked && sel != null,
      showNext: !handed && !allDone && idx < total - 1 && (locked || sel == null),
      showNextQuiet: ((handed || allDone) && idx < total - 1) || (!locked && sel != null && idx < total - 1),
      showJump: !handed && !allDone && idx === total - 1 && (locked || sel == null),
      jumpLabel: 'NEXT UNANSWERED',
      showHandIn: !handed && allDone,
      showSummary: handed,

      handStamp: st.handedAt || '', handMeta: pad(nDone) + ' / ' + pad(total) + ' ANSWERED \u00B7 ' + this.mmss(st.elapsed) + ' ON THE CLOCK',
      doneEyebrow: 'Handed in ' + (st.handedAt || '') + (st.late ? ' \u00B7 2 days late' : ''),
      doneKicker: st.late ? 'Marked \u00B7 handed in late' : 'Marked \u00B7 week 04',
      scoreFrac: nRight + ' / ' + total, scorePct: pctVal + '%',
      doneStats: [
        { label: 'RIGHT', value: pad(nRight) },
        { label: 'WRONG', value: pad(total - nRight) },
        { label: 'TIME TAKEN', value: this.mmss(st.elapsed) }
      ].map((s, i) => Object.assign(s, { edge: i < 2 ? '1px solid var(--st-room-line)' : 'none', pl: i ? '15px' : '0' })),
      wrongList: wrongList, noneWrong: wrongList.length === 0,
      wrongCount: pad(wrongList.length) + ' OF ' + pad(total),
      reviewAll: this.reviewAll, reviewLabel: 'Look through all ' + total,
      goClass: this.goClass
    };
  }
}

c.v:
body { margin: 0; background: #FBF3E6; }
a { color: var(--ks3-accent-text); text-decoration: none; }
a:hover { color: var(--ks3-accent-hover); }
button { font-family: inherit; }
@keyframes mrbMark { from { transform: scale(.5); opacity: 0 } 62% { transform: scale(1.09); opacity: 1 } to { transform: scale(1); opacity: 1 } }
@keyframes mrbNote { from { opacity: 0; transform: translateY(-6px) } to { opacity: 1; transform: none } }
@keyframes mrbTick { from { stroke-dashoffset: 22 } to { stroke-dashoffset: 0 } }
@keyframes mrbStamp { 0% { transform: scale(1.55) rotate(-9deg); opacity: 0 } 58% { transform: scale(.97) rotate(-1.4deg); opacity: 1 } 100% { transform: scale(1) rotate(-2.5deg); opacity: 1 } }
@keyframes mrbRing { from { transform: scale(.35); opacity: .5 } to { transform: scale(2.6); opacity: 0 } }
@keyframes mrbRise { from { opacity: 0; transform: translateY(10px) } to { opacity: 1; transform: none } }
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001s !important; animation-delay: 0s !important; transition-duration: .001s !important }
}

class view.logic:
class Component extends DCLogic {
  rootRef = MrbRef();

  state = {
    view: 'class', w: 1200, menu: false,
    tab: 'all', week: null, open: null,
    bench: { t1: false, t2: false, t3: false },
    boardWeek: 4, boardSize: 5,
    qi: 0, pick: null, checked: false, right: 0, streak: 3
  };

  work = [
    { id: 'a5', week: 4, title: 'Cells & microscopy', brief: '8 questions \u00B7 draws on this week\u2019s lessons', status: 'open', detail: 'SET MON 15 SEP \u00B7 8 QUESTIONS \u00B7 DUE THU 18:00' },
    { id: 'a4', week: 3, title: 'Digestion', brief: '6 questions \u00B7 enzymes and the gut', status: 'marked', score: 82, detail: 'MARKED 11 SEP \u00B7 6 OF 8 QUESTIONS RIGHT',
      notes: [
        { text: 'Questions 3 and 7 put the enzyme in the wrong part of the gut. Read the second half of the lesson before the next one.', meta: 'ON QUESTIONS 03, 07 \u00B7 11 SEP' },
        { text: 'Handed in early and the working was set out clearly. Same again this week.', meta: 'ON THE WHOLE PIECE \u00B7 11 SEP' }
      ], items: [1, 1, 0, 1, 1, 1, 0, 1] },
    { id: 'a3', week: 3, title: 'Movement & joints', brief: '5 questions \u00B7 muscles and bones', status: 'marked', score: 71, retake: true, detail: 'MARKED 9 SEP \u00B7 3 OF 5 QUESTIONS RIGHT',
      notes: [{ text: 'Two answers named the wrong bone. The retake is open until Friday and the better mark counts.', meta: 'ON QUESTIONS 02, 04 \u00B7 9 SEP' }],
      items: [1, 0, 1, 0, 1] },
    { id: 'a2', week: 2, title: 'Gas exchange', brief: '10 questions \u00B7 lungs and breathing', status: 'pending', late: true, detail: 'HANDED IN 2 DAYS LATE \u00B7 WITH MR BADMUS' },
    { id: 'a1', week: 1, title: 'Cell parts', brief: '8 questions \u00B7 starter set', status: 'marked', score: 95, detail: 'MARKED 2 SEP \u00B7 8 OF 8 QUESTIONS RIGHT',
      notes: [{ text: 'Full marks. Move on to the microscopy lesson before Thursday.', meta: 'ON THE WHOLE PIECE \u00B7 2 SEP' }], items: [1, 1, 1, 1, 1, 1, 1, 1] },
    { id: 'a0', week: 1, title: 'Lab safety check', brief: '8 questions \u00B7 before any practical', status: 'missed', detail: 'CLOSED 1 SEP \u00B7 NOT HANDED IN' }
  ];

  roster = [
    { id: 's1', name: 'Tiwa A.', mono: 'TA' }, { id: 's2', name: 'Marcus O.', mono: 'MO' },
    { id: 's3', name: 'Ayo B.', mono: 'AY', me: true }, { id: 's4', name: 'Hafsah I.', mono: 'HI' },
    { id: 's5', name: 'Daniel K.', mono: 'DK' }, { id: 's6', name: 'Priya S.', mono: 'PS' },
    { id: 's7', name: 'Ronke E.', mono: 'RE' }, { id: 's8', name: 'Jamie L.', mono: 'JL' },
    { id: 's9', name: 'Oscar N.', mono: 'ON' }, { id: 's10', name: 'Zainab F.', mono: 'ZF' },
    { id: 's11', name: 'Ethan C.', mono: 'EC' }, { id: 's12', name: 'Mira P.', mono: 'MP' }
  ];

  weekPts = {
    1: [72, 88, 64, 91, 55, 79, 83, 47, 68, 94, 60, 51],
    2: [95, 81, 78, 70, 66, 86, 74, 58, 90, 62, 49, 84],
    3: [84, 92, 88, 76, 71, 63, 97, 55, 67, 80, 73, 59],
    4: [98, 91, 94, 86, 74, 88, 69, 62, 80, 77, 71, 65]
  };

  lessonDefs = [
    { num: '01', name: 'Life processes and cells', meta: 'READ \u00B7 4 RUNGS DONE' },
    { num: '02', name: 'Using a microscope', meta: 'THIS WEEK \u00B7 SET IN THE ASSIGNMENT', on: true },
    { num: '03', name: 'Animal and plant cells', meta: 'NOT OPENED' },
    { num: '04', name: 'Specialised cells', meta: 'NOT OPENED' }
  ];

  /* Real KS3 ladder questions, rungs 1-2, across the topics this class has covered.
     Each distractor carries the feedback written against it in the lesson. */
  questions = [
    { topic: 'CELLS & MICROSCOPY', a: 'B',
      q: 'An eyepiece lens of 10 and an objective lens of 40 are used together. What is the total magnification?',
      o: ['50, because the two lens powers are added together',
          '400, because the two lens powers are multiplied together',
          '40, because the objective lens does all of the magnifying',
          '4, because the objective is divided by the eyepiece'],
      f: ['Magnification multiplies at each lens. It is never added.',
          'Right. Each lens magnifies the image the next one receives, so the two powers multiply.',
          'The objective magnifies first, but the eyepiece then magnifies that image again.',
          'Nothing is divided here. Both lenses enlarge the image.'] },
    { topic: 'CELL PARTS', a: 'A',
      q: 'Which structure would you find in a plant cell but never in an animal cell?',
      o: ['A chloroplast, where light is absorbed for photosynthesis',
          'A nucleus, which holds the genetic material',
          'A mitochondrion, which releases energy from glucose',
          'A cell membrane, which controls what enters the cell'],
      f: ['Right. Animal cells cannot photosynthesise, so they have no chloroplasts.',
          'Both plant and animal cells have a nucleus.',
          'Both plant and animal cells respire, so both have mitochondria.',
          'Every cell has a membrane, plant or animal.'] },
    { topic: 'CELLS & MICROSCOPY', a: 'B',
      q: 'What is the job of the cell membrane?',
      o: ['To hold the cell in a rigid shape',
          'To control which substances enter and leave the cell',
          'To store sap and keep the cell firm',
          'To carry the instructions for making proteins'],
      f: ['That is the cell wall, and only plant cells have one.',
          'Right. The membrane is partially permeable, so some substances pass through and others do not.',
          'That is the vacuole, which sits inside the cell.',
          'That is the nucleus.'] },
    { topic: 'DIGESTION', a: 'A',
      q: 'Why does the body use enzymes to digest food?',
      o: ['They break large food molecules into small ones the body can absorb',
          'They squeeze the food along the gut a little at a time',
          'They neutralise the acid that the stomach makes',
          'They carry the digested food to the cells that need it'],
      f: ['Right. Only small molecules can pass through the wall of the small intestine.',
          'That is peristalsis, done by muscles in the gut wall.',
          'Bile does that, and bile is not an enzyme.',
          'The blood does that, after absorption.'] },
    { topic: 'MOVEMENT & JOINTS', a: 'B',
      q: 'Why do muscles have to work in pairs across a joint?',
      o: ['One muscle is stronger, so the weaker one helps it',
          'A muscle can only pull, so a second muscle pulls the bone back',
          'Two muscles contracting together can lift twice the weight',
          'Each muscle is joined to a different bone, so both must move'],
      f: ['Strength is not the reason. Think about what a muscle can and cannot do.',
          'Right. Muscles pull but never push, so an antagonistic pair moves the bone both ways.',
          'In a pair, one contracts while the other relaxes. They do not contract together.',
          'Both muscles of a pair cross the same joint.'] },
    { topic: 'GAS EXCHANGE', a: 'B',
      q: 'Alveoli are covered in a dense network of capillaries. Why does that matter?',
      o: ['It keeps the air inside the lungs warm',
          'It gives oxygen a very short distance to diffuse into the blood',
          'It pushes the air back out when you breathe out',
          'It lets the blood carry whole bubbles of air to the muscles'],
      f: ['Air is warmed in the nose and airways, and that is not what the capillaries are for.',
          'Right. A short diffusion distance and a large surface area together make gas exchange fast.',
          'The diaphragm and the ribs do that.',
          'Only dissolved gases cross into the blood, never bubbles.'] }
  ];

  componentDidMount() {
    const el = this.rootRef.current;
    if (!el) return;
    this.measure = () => {
      const w = el.getBoundingClientRect().width;
      if (w && Math.abs(w - this.state.w) > 1) this.setState({ w: w });
    };
    window.addEventListener('resize', this.measure);
    window.addEventListener('orientationchange', this.measure);
    if (window.visualViewport) window.visualViewport.addEventListener('resize', this.measure);
    /* settle poll: catches font load, scrollbar arrival and any host reframe
       that a resize event does not announce */
    let ticks = 0;
    this.poll = setInterval(() => { this.measure(); if (++ticks > 24) clearInterval(this.poll); }, 250);
    this.measure();
    requestAnimationFrame(this.measure);
  }
  componentWillUnmount() {
    window.removeEventListener('resize', this.measure);
    window.removeEventListener('orientationchange', this.measure);
    if (window.visualViewport) window.visualViewport.removeEventListener('resize', this.measure);
    clearInterval(this.poll);
  }

  go = (view) => this.setState({ view: view, open: null, menu: false });
  toggleMenu = () => this.setState((s) => ({ menu: !s.menu }));
  pickWeek = (n) => this.setState((s) => ({ week: s.week === n ? null : n }));
  clearWeek = () => this.setState({ week: null });
  resetFilters = () => this.setState({ week: null, tab: 'all' });
  pickTab = (id) => this.setState({ tab: id });
  toggleRow = (id) => this.setState((s) => ({ open: s.open === id ? null : id }));
  toggleTask = (k) => this.setState((s) => ({ bench: Object.assign({}, s.bench, { [k]: !s.bench[k] }) }));
  pickBoardWeek = (w) => this.setState({ boardWeek: w });
  toggleSize = () => this.setState((s) => ({ boardSize: s.boardSize === 5 ? 10 : 5 }));

  /* Routes to /class/8r-sc1/assignments/:id, an existing platform page.
     Here it records the visit: task one ticks, as it would on return. */
  openAssignment = () => this.setState((s) => ({ bench: Object.assign({}, s.bench, { t1: true }) }));

  choose = (k) => { if (!this.state.checked) this.setState({ pick: k }); };
  advance = () => this.setState((s) => {
    if (!s.checked) {
      if (!s.pick) return {};
      const ok = s.pick === this.questions[s.qi].a;
      return { checked: true, right: s.right + (ok ? 1 : 0), streak: ok ? s.streak + 1 : 0 };
    }
    return { qi: s.qi + 1, pick: null, checked: false };
  });
  skipQuestion = () => this.setState((s) => ({ qi: s.qi + 1, pick: null, checked: false, streak: 0 }));
  newRound = () => this.setState({ qi: 0, pick: null, checked: false, right: 0 });

  renderVals() {
    const st = this.state;
    const fresh = (this.props.classState ?? 'Work set') === 'Fresh class';
    const hideScores = this.props.hideScores ?? false;
    const forced = { 'Phone 360': 360, 'Phone 390': 390, 'Tablet 820': 820, 'Desktop 1460': 1460 }[this.props.layout ?? 'Auto'];
    const W = forced || st.w;

    /* Breakpoints. desk >= 1024 · tablet 720-1023 · phone < 720 */
    const desk = W >= 1024;
    const wide = W >= 720;
    const narrow = !wide;
    const onClass = st.view === 'class';
    const dash = '\u2014';
    const pad = (n) => (n < 10 ? '0' + n : String(n));
    const pc = (a, b) => (b ? Math.round((a / b) * 100) + '%' : '0%');
    const all = fresh ? [] : this.work;

    const marked = all.filter((w) => w.status === 'marked');
    const handed = all.filter((w) => w.status === 'marked' || w.status === 'pending');
    const onTime = handed.filter((w) => !w.late).length;
    const avg = marked.length ? Math.round(marked.reduce((s, w) => s + w.score, 0) / marked.length) : null;

    const readings = ([
      { label: 'Handed in', value: all.length ? handed.length + '/' + all.length : dash, caption: 'THIS TERM', pct: pc(handed.length, all.length) },
      { label: 'On time', value: handed.length ? onTime + '/' + handed.length : dash, caption: 'OF HANDED IN', pct: pc(onTime, handed.length), bar: 'var(--ks3-ok)' },
      { label: 'Avg score', value: avg == null ? dash : avg + '%', caption: marked.length ? marked.length + ' MARKED' : 'NOT MARKED YET', pct: avg == null ? '0%' : avg + '%' },
      { label: 'Recall', value: fresh ? '0' : '46', caption: 'ANSWERED \u00B7 WK 04', pct: fresh ? '0%' : '77%' }
    ]).map((r) => Object.assign({ bar: 'var(--st-accent)' }, r));

    const weeks = [];
    for (let n = 1; n <= 12; n++) {
      const items = all.filter((w) => w.week === n);
      const sel = st.week === n;
      weeks.push({
        num: pad(n), onClick: () => this.pickWeek(n),
        trough: n <= 4 ? 'var(--st-rule-fact)' : 'var(--st-crumb-bg)',
        stackH: !items.length ? '0%' : items.length > 1 ? '100%' : '70%',
        segs: items.map((w) => ({ bg: w.status === 'open' ? 'var(--st-accent)' : w.status === 'missed' ? 'var(--err)' : 'var(--st-ink)' })),
        ring: sel ? '0 0 0 1.5px var(--st-ink)' : 'none',
        numColor: sel ? 'var(--st-ink)' : n === 4 ? 'var(--ks3-accent-text)' : 'var(--st-ghost)',
        nowDot: n === 4 ? 'var(--st-accent)' : 'transparent'
      });
    }

    const tabDefs = [
      { id: 'all', label: 'All', n: all.length },
      { id: 'todo', label: 'To do', n: all.filter((w) => w.status === 'open' || w.status === 'missed').length },
      { id: 'marked', label: 'Marked', n: marked.length }
    ];
    const tabs = tabDefs.map((t) => ({
      label: t.label + ' ' + t.n, onClick: () => this.pickTab(t.id),
      bg: st.tab === t.id ? 'var(--st-paper)' : 'transparent',
      color: st.tab === t.id ? 'var(--st-ink)' : 'var(--st-caption)'
    }));

    let list = all;
    if (st.tab === 'todo') list = list.filter((w) => w.status === 'open' || w.status === 'missed');
    if (st.tab === 'marked') list = list.filter((w) => w.status === 'marked');
    if (st.week != null) list = list.filter((w) => w.week === st.week);

    const rows = list.map((w) => {
      const isMarked = w.status === 'marked';
      const showScore = isMarked && !hideScores;
      const expanded = st.open === w.id;
      const longWord = w.status === 'open' ? 'DUE THU 18:00' : w.status === 'pending' ? 'WITH MR BADMUS' : w.status === 'missed' ? 'MISSED' : 'MARKED';
      const shortWord = w.status === 'open' ? 'DUE THU' : w.status === 'pending' ? 'SENT' : w.status === 'missed' ? 'MISSED' : 'MARKED';
      return {
        wk: 'W' + pad(w.week), title: w.title, brief: w.brief,
        metaLine: 'W' + pad(w.week) + ' \u00B7 ' + longWord,
        isMarked: isMarked, isPending: w.status === 'pending', isMissed: w.status === 'missed', isOpen: w.status === 'open',
        showScore: showScore, scoreText: w.score + '%',
        showWord: !showScore && wide, word: wide ? longWord : shortWord,
        wordColor: w.status === 'open' ? 'var(--ks3-accent-text)' : w.status === 'missed' ? 'var(--err)' : 'var(--st-caption)',
        showHint: wide && !expanded,
        hintText: isMarked ? 'READ FEEDBACK' : w.status === 'open' ? 'OPEN IT' : w.status === 'pending' ? 'SEE IT' : 'OPTIONS',
        detail: w.detail, retake: !!w.retake,
        hasNotes: !!w.notes, notes: w.notes || [],
        hasBreakdown: !!w.items,
        items: (w.items || []).map((ok, i) => ({
          numeral: pad(i + 1), ok: ok === 1, bad: ok === 0,
          bg: ok === 1 ? 'var(--st-paper)' : 'transparent',
          border: ok === 1 ? 'var(--st-rule)' : 'var(--err)',
          color: ok === 1 ? 'var(--st-body)' : 'var(--err)'
        })),
        footNote: isMarked ? 'MARKS ARE FINAL UNLESS A RETAKE IS OPEN' : w.status === 'open' ? 'COUNTS TOWARDS WEEK 04' : '',
        primaryLabel: w.status === 'open' ? 'Open the assignment' : w.retake ? 'Retake it' : isMarked ? 'Open the lesson' : w.status === 'pending' ? 'See what you sent' : 'Ask for an extension',
        primary: w.status === 'open' || w.retake ? this.openAssignment : () => this.go('recall'),
        expanded: expanded, caret: expanded ? '225deg' : '45deg',
        toggle: () => this.toggleRow(w.id)
      };
    });

    const doneCount = ['t1', 't2', 't3'].filter((k) => st.bench[k]).length;
    const benchTasks = [
      { key: 't1', label: 'Open it' },
      { key: 't2', label: 'Answer the eight questions' },
      { key: 't3', label: 'Hand it in' }
    ].map((t) => {
      const done = !!st.bench[t.key];
      return {
        label: t.label, done: done,
        boxBg: done ? 'var(--st-ember)' : 'transparent',
        boxBorder: done ? 'var(--st-ember)' : 'var(--st-room-line-strong)',
        color: done ? 'var(--st-room-faint)' : 'var(--st-room-text)',
        toggle: () => this.toggleTask(t.key)
      };
    });

    const bigVal = 'clamp(15px,1.35cqw,17px)';
    const docket = fresh ? [
      { label: 'QUESTIONS', value: dash, font: '600 ' + bigVal + '/1.3 var(--st-display)' },
      { label: 'DRAWS ON', value: dash, font: '500 ' + bigVal + '/1.3 var(--st-ui)' },
      { label: 'SET', value: dash, font: '500 ' + bigVal + '/1.3 var(--st-ui)' },
      { label: 'DUE', value: dash, font: '500 ' + bigVal + '/1.3 var(--st-ui)' }
    ] : [
      { label: 'QUESTIONS', value: '8', font: '600 clamp(19px,1.7cqw,23px)/1 var(--st-display)' },
      { label: 'DRAWS ON', value: 'Using a microscope', font: '500 ' + bigVal + '/1.3 var(--st-ui)' },
      { label: 'SET', value: 'Mon 15 Sep', font: '500 ' + bigVal + '/1.3 var(--st-ui)' },
      { label: 'DUE', value: 'Thu 18 Sep, 18:00', font: '500 ' + bigVal + '/1.3 var(--st-ui)' }
    ];

    const lessons = this.lessonDefs.map((l) => ({
      num: l.num, name: l.name, meta: l.meta,
      border: l.on ? 'var(--st-accent)' : 'var(--st-rule-soft)',
      bg: l.on ? 'var(--st-chip-tint)' : 'var(--st-paper)',
      numBg: l.on ? 'var(--st-paper)' : 'var(--st-num-well)',
      numBorder: l.on ? 'var(--st-chip-tint-border)' : 'var(--st-rule)',
      numColor: l.on ? 'var(--ks3-accent-text)' : 'var(--st-caption)',
      metaColor: l.on ? 'var(--ks3-accent-text)' : 'var(--st-faint)'
    }));

    const qi = Math.min(st.qi, 5);
    const q = this.questions[qi];
    const keys = ['A', 'B', 'C', 'D'];
    const options = q.o.map((t, i) => {
      const k = keys[i];
      const chosen = st.pick === k;
      const isAns = q.a === k;
      const ok = st.checked && isAns;
      const bad = st.checked && chosen && !isAns;
      return {
        key: k, text: t, onClick: () => this.choose(k), ok: ok, bad: bad,
        bg: ok ? 'rgba(85,179,106,0.12)' : chosen ? '#241E17' : 'transparent',
        border: bad ? 'var(--err)' : ok ? 'var(--st-ok-room)' : chosen ? 'var(--st-room-line-strong)' : 'var(--st-room-line)',
        keyBg: chosen || ok ? 'var(--st-ember)' : 'transparent',
        keyBorder: chosen || ok ? 'var(--st-ember)' : 'var(--st-room-line-strong)',
        keyColor: chosen || ok ? '#15110C' : 'var(--st-room-muted)',
        color: ok || chosen ? 'var(--st-cream)' : 'var(--st-room-text)'
      };
    });
    const pickIdx = keys.indexOf(st.pick);
    const rightPick = st.checked && st.pick === q.a;
    const pips = this.questions.map((x, i) => ({
      w: i === st.qi ? '26px' : '12px',
      bg: i < st.qi ? 'var(--st-ember)' : i === st.qi ? 'var(--st-cream)' : 'var(--st-room-line)'
    }));

    const wk = st.boardWeek;
    const table = this.roster.map((s, i) => {
      const pts = wk === 'term' ? [1, 2, 3, 4].reduce((a, w) => a + this.weekPts[w][i], 0) : this.weekPts[wk][i];
      const capOn = wk === 'term' ? 160 : 40, capRe = wk === 'term' ? 80 : 20;
      const onT = Math.min(capOn, Math.round(pts * 0.4));
      const rec = Math.min(capRe, Math.round(pts * 0.19));
      const sc = Math.max(0, pts - onT - rec);
      return { id: s.id, name: s.name, mono: s.mono, me: !!s.me, pts: pts, onT: onT, sc: sc, rec: rec };
    }).sort((a, b) => b.pts - a.pts || a.name.localeCompare(b.name));

    let prev = null;
    if (wk !== 'term' && wk > 1) {
      prev = this.roster.map((s, i) => ({ id: s.id, pts: this.weekPts[wk - 1][i] })).sort((a, b) => b.pts - a.pts).map((x) => x.id);
    }
    const top = table[0];
    const maxPts = top ? top.pts : 1;
    let streak = 0;
    if (wk !== 'term' && top) {
      for (let w = wk; w >= 1; w--) {
        const lead = this.roster.map((s, i) => ({ id: s.id, pts: this.weekPts[w][i] })).sort((a, b) => b.pts - a.pts)[0];
        if (lead.id === top.id) streak++; else break;
      }
    }
    const rankOf = (id) => table.findIndex((x) => x.id === id) + 1;
    const mkDelta = (id) => {
      if (!prev) return { up: false, down: false, flat: true };
      const was = prev.indexOf(id) + 1, now = rankOf(id);
      return { up: now < was, down: now > was, flat: now === was };
    };
    const size = st.boardSize;
    const chasers = table.slice(1, size).map((r) => {
      const d = mkDelta(r.id);
      return {
        rank: pad(rankOf(r.id)), name: r.name, mono: r.mono, me: r.me, points: r.pts,
        rankColor: r.me ? 'var(--ks3-accent-text)' : 'var(--st-ghost)',
        rowBg: r.me ? 'var(--st-chip-tint)' : 'transparent',
        rowRing: r.me ? '0 0 0 1px var(--st-chip-tint-border)' : 'none',
        monoBorder: r.me ? 'var(--st-accent)' : 'var(--st-edge)',
        barWidth: Math.round((r.pts / maxPts) * 100) + '%',
        wOnTime: Math.round((r.onT / r.pts) * 100) + '%',
        wScore: Math.round((r.sc / r.pts) * 100) + '%',
        wRecall: Math.round((r.rec / r.pts) * 100) + '%',
        up: d.up, down: d.down, flat: d.flat
      };
    });
    const meRow = table.find((r) => r.me);
    const meRank = meRow ? rankOf(meRow.id) : 0;
    const pinned = meRow ? {
      rank: pad(meRank), name: meRow.name, mono: meRow.mono, points: meRow.pts,
      gapText: (table[size - 2] ? table[size - 2].pts - meRow.pts : 0) + ' POINTS OFF THE TOP ' + (size === 5 ? 'FIVE' : 'TEN')
    } : {};
    const leader = top ? {
      name: top.name, mono: top.mono, points: top.pts,
      streakText: wk === 'term' ? 'TERM LEADER' : streak > 1 ? streak + ' WEEKS AT THE TOP' : 'NEW AT THE TOP',
      deltaText: top.me ? 'THAT IS YOU' : pad(top.pts - (table[1] ? table[1].pts : 0)) + ' POINTS CLEAR',
      wOnTime: Math.round((top.onT / top.pts) * 100) + '%',
      wScore: Math.round((top.sc / top.pts) * 100) + '%',
      wRecall: Math.round((top.rec / top.pts) * 100) + '%',
      parts: [{ label: 'ON TIME', value: top.onT }, { label: 'SCORE', value: top.sc }, { label: 'RECALL', value: top.rec }].map((p, i) => Object.assign(p, { edge: i < 2 ? '1px solid var(--st-room-line)' : 'none' }))
    } : {};
    const boardWeeks = [1, 2, 3, 4, 'term'].map((w) => ({
      label: w === 'term' ? 'TERM' : 'W' + pad(w), onClick: () => this.pickBoardWeek(w),
      bg: st.boardWeek === w ? 'var(--st-ink)' : 'transparent',
      color: st.boardWeek === w ? 'var(--st-ground)' : 'var(--st-caption)',
      border: st.boardWeek === w ? 'var(--st-ink)' : 'var(--st-rule)'
    }));

    const nav = [
      { label: 'My class', onClick: () => this.go('class'), on: onClass },
      { label: 'Recall', onClick: () => this.go('recall'), on: !onClass }
    ].map((n) => ({
      label: n.label, onClick: n.onClick,
      color: n.on ? 'var(--st-ink)' : 'var(--st-muted)',
      under: n.on ? 'var(--st-accent)' : 'transparent'
    }));

    return {
      rootRef: this.rootRef,
      frameW: forced ? forced + 'px' : '100%',
      frameEdge: forced ? '1px solid var(--st-rule)' : 'none',
      wide: wide, narrow: narrow,

      /* the eight discrete layout switches — everything else is clamp() on cqw */
      benchCols: desk ? 'minmax(0,1fr) minmax(300px,440px)' : 'minmax(0,1fr)',
      docketOrder: desk ? 3 : 1,
      docketCols: desk ? 'minmax(0,1fr)' : 'repeat(auto-fit,minmax(148px,1fr))',
      statsBasis: desk ? '340px' : '100%',
      statsMax: desk ? '576px' : 'none',
      ghostRight: desk ? '-14px' : '12px',
      docketDir: desk ? 'row' : 'column',
      docketItems: desk ? 'baseline' : 'flex-start',
      docketGap: desk ? '14px' : '9px',
      docketPush: desk ? 'auto' : '0',
      docketText: desk ? 'right' : 'left',
      railDisplay: desk ? 'grid' : 'flex',
      railAlign: desk ? 'start' : 'stretch',
      spineCols: narrow ? 'repeat(6,minmax(40px,1fr))' : 'repeat(12,46px)',
      rowCols: wide ? '46px 20px minmax(0,1fr) auto' : '18px minmax(0,1fr) auto',
      boardCols: desk ? 'minmax(300px,0.92fr) minmax(0,1.35fr)' : 'minmax(0,1fr)',
      chaseCols: wide ? '30px 34px minmax(0,1fr) 62px 22px' : '24px 30px minmax(0,1fr) 52px 16px',
      recallCols: desk ? 'minmax(0,1fr) 356px' : 'minmax(0,1fr)',
      optCols: desk ? '1fr 1fr' : 'minmax(0,1fr)',

      onClass: onClass, onRecall: !onClass,
      fresh: fresh, hasWork: !fresh,
      showSpine: this.props.showSpine ?? true,
      nav: nav, menuOpen: st.menu, toggleMenu: this.toggleMenu,
      menuRing: st.menu ? 'var(--st-accent)' : 'var(--st-edge)',
      crumbLast: onClass ? 'Overview' : 'Recall',
      crumbRight: onClass ? (wide ? 'AUTUMN TERM \u00B7 WEEK 04 / 12' : 'WK 04 / 12') : 'SIX A ROUND',
      goClass: () => this.go('class'), goRecall: () => this.go('recall'),
      openAssignment: this.openAssignment,

      readings: readings, weeks: weeks, tabs: tabs, rows: rows, lessons: lessons,
      weekPicked: st.week != null, noWeekPicked: st.week == null,
      weekChipText: 'WEEK ' + pad(st.week || 1) + ' ONLY',
      clearWeek: this.clearWeek, resetFilters: this.resetFilters,
      canReset: st.week != null || st.tab !== 'all',
      noRows: rows.length === 0,
      emptyNote: fresh ? 'No work set in this class yet' : 'Nothing under this filter',

      benchTasks: benchTasks, benchPct: Math.round((doneCount / 3) * 100) + '%', benchDoneText: doneCount + ' / 3 DONE',
      docket: docket,
      docketKicker: fresh ? 'Nothing set' : 'This week\u2019s assignment',
      docketFlag: fresh ? 'BENCH CLEAR' : 'OPEN',
      docketLeft: fresh ? 'No deadline' : '2 days left',
      docketWorth: fresh ? '\u2014' : '40 POINTS AT STAKE',
      docketElapsed: fresh ? '0%' : '58%',

      shoutouts: fresh ? [] : [
        { who: 'MB', text: 'Best score in the class on digestion this week.', meta: 'MR BADMUS \u00B7 2 DAYS AGO' },
        { who: 'MB', text: 'Third week running you handed in first. Keep it.', meta: 'MR BADMUS \u00B7 1 WEEK AGO' }
      ],
      noShouts: fresh, shoutCount: fresh ? '00' : '02',
      retrievalCount: fresh ? '0' : '46',

      recallMeter: 'QUESTION ' + pad(Math.min(st.qi + 1, 6)) + ' / 06',
      recallMeterPct: Math.round((Math.min(st.qi, 6) / 6) * 100) + '%',
      roundLive: st.qi < 6, roundDone: st.qi >= 6,
      qCounter: 'QUESTION ' + pad(Math.min(st.qi + 1, 6)) + ' / 06 \u00B7 ' + q.topic,
      question: q.q, options: options, pips: pips,
      showFeedback: st.checked && pickIdx > -1,
      fbLabel: rightPick ? 'CORRECT' : 'NOT THIS ONE',
      fbEdge: rightPick ? 'var(--st-ok-room)' : 'var(--st-ember)',
      // ⊕ MRB-270 phase 3, RULED 20 Aug 2026: the LABEL is text, and
      // --st-ok-room is graphic-only. The 3px edge above keeps it.
      fbLabelColor: rightPick ? 'var(--ks3-ok-dark)' : 'var(--st-ember)',
      fbText: pickIdx > -1 ? q.f[pickIdx] : '',
      primaryRecall: this.advance, skipQuestion: this.skipQuestion, newRound: this.newRound,
      recallBtnLabel: st.checked ? 'Next question' : 'Check',
      recallBtnBg: st.pick || st.checked ? 'var(--ks3-accent-text)' : 'transparent',
      recallBtnColor: st.pick || st.checked ? 'var(--st-paper)' : 'var(--st-room-muted)',
      recallBtnBorder: st.pick || st.checked ? 'var(--ks3-accent-text)' : 'var(--st-room-line)',
      streakText: st.streak > 0 ? 'STREAK ' + pad(st.streak) : 'STREAK BROKEN',
      roundScore: pad(st.right),
      roundNote: 'Six answers logged against Week 04. Recall is worth 20 of the 100 points on the leaderboard.',
      recallStats: [{ label: 'BEST STREAK', value: pad(Math.max(9, st.streak)) }, { label: 'ROUNDS', value: '08' }],

      hasBoard: !fresh, noBoard: fresh,
      boardScopeNote: wk === 'term' ? 'WHOLE AUTUMN TERM' : wk === 4 ? 'CURRENT WEEK' : 'WEEK ' + pad(wk) + ' \u00B7 FINAL',
      boardWeeks: boardWeeks, toggleSize: this.toggleSize,
      sizeLabel: size === 5 ? 'SHOW TOP 10' : 'SHOW TOP 5',
      leaderEyebrow: wk === 'term' ? 'Top of the term' : 'Top of week ' + pad(wk),
      leader: leader, chasers: chasers,
      showPinned: !fresh && meRank > Math.max(1, size - 1), pinned: pinned
    };
  }
}

c.v:
body { margin: 0; background: #FBF3E6; }
a { color: var(--ks3-accent-text); text-decoration: none; }
a:hover { color: var(--ks3-accent-hover); }
button { font-family: inherit; }
